// Removes o from all passed in related items' relationships struct.
func (o *PlanoContasFinanceiro) RemoveCTB(ctx context.Context, exec boil.ContextExecutor, related *ContaBancarium) error {
	var err error

	queries.SetScanner(&o.CTBID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("ctb_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.CTB = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.CTBPlanoContasFinanceiros {
		if queries.Equal(o.CTBID, ri.CTBID) {
			continue
		}

		ln := len(related.R.CTBPlanoContasFinanceiros)
		if ln > 1 && i < ln-1 {
			related.R.CTBPlanoContasFinanceiros[i] = related.R.CTBPlanoContasFinanceiros[ln-1]
		}
		related.R.CTBPlanoContasFinanceiros = related.R.CTBPlanoContasFinanceiros[:ln-1]
		break
	}
	return nil
}

